import { scanMiniappBundleEntries } from "./lib/miniapp-bundle-check.mjs";

const requiredPaths = [
  "app.js",
  "app.json",
  "app.wxss",
  "generated/public-build-config.js",
  "pages/launch/index.js",
  "pages/launch/index.json",
  "pages/launch/index.wxml",
  "pages/launch/index.wxss",
  "pages/recovery/index.js",
  "pages/recovery/index.json",
  "pages/recovery/index.wxml",
  "pages/recovery/index.wxss",
  "sitemap.json",
];
const generatedHeader = [
  '"use strict";',
  "// @generated by synthetic bundle fixture.",
  `// source-fingerprint: sha256:${"a".repeat(64)}`,
].join("\n");
const validEntries = requiredPaths.map((path) => ({
  content:
    path === "app.json"
      ? JSON.stringify({
          pages: ["pages/launch/index", "pages/recovery/index"],
        })
      : path === "generated/public-build-config.js"
        ? generatedHeader
        : "",
  path,
}));
const errors = [];

if (scanMiniappBundleEntries(validEntries).length !== 0) {
  errors.push("MINIAPP_BUNDLE_FIXTURE_VALID_FAILED");
}

const cases = [
  {
    expectedRuleId: "MINIAPP_BUNDLE_FORBIDDEN_IMPORT",
    mutation: {
      content: 'require("node:crypto");',
      path: "pages/launch/index.js",
    },
  },
  {
    expectedRuleId: "MINIAPP_BUNDLE_SECRET_IDENTIFIER",
    mutation: {
      content: 'const OPENAI_API_KEY = "synthetic-canary";',
      path: "pages/launch/index.js",
    },
  },
  {
    expectedRuleId: "MINIAPP_BUNDLE_TABBAR_FORBIDDEN",
    mutation: {
      content: JSON.stringify({
        pages: ["pages/launch/index", "pages/recovery/index"],
        tabBar: {},
      }),
      path: "app.json",
    },
  },
];

for (const testCase of cases) {
  const mutated = validEntries.map((entry) =>
    entry.path === testCase.mutation.path ? testCase.mutation : entry,
  );
  const diagnostics = scanMiniappBundleEntries(mutated);
  if (
    !diagnostics.some(
      (diagnostic) => diagnostic.ruleId === testCase.expectedRuleId,
    )
  ) {
    errors.push(`MINIAPP_BUNDLE_FIXTURE_MISSED: ${testCase.expectedRuleId}`);
  }
}

if (errors.length > 0) {
  console.error(errors.join("\n"));
  process.exitCode = 1;
} else {
  console.log(
    `Miniapp bundle fixture Gate passed ${cases.length} known-fail cases and one known-pass bundle.`,
  );
}
